// Original workplace satire adapted from privately reviewed recollections and
// the creator's quiz. These scenes and their dialogue are fictional extensions;
// private source text and the answer bank are never shipped with the game.
import { LEGAL_CAST_EVENTS_V35 } from './events-cast-v35-legal.js';
const c = (text, result, index, override = {}) => ({
  text, detail: '', result,
  delta: [
    { skill: 6, trust: 5, energy: -7, mood: -3 },
    { lick: 6, trust: -3, energy: -6, mood: -5 },
    { slack: 7, trust: 4, energy: -5, mood: 4 }
  ].map(d => ({ ...d }))[index],
  flags: index === 0 ? ['evidence'] : index === 1 ? ['loop'] : ['archive'],
  ...(index === 2 ? { wild: true } : {}), ...override
});
let sceneNumber = 0;
const scene = (speaker, slug, title, body, wing, answers, roles = [], sources = ['officeLore']) => ({
  id: `cast35-${speaker}-${slug}`, title, body, wing, speaker,
  era: '同事日常・今天換誰登場', minRules: 35,
  minTurn: sceneNumber++ % 2, weight: 1.35,
  sourceIds: [...new Set([...sources, 'characterFiction'])],
  choices: answers.map(([text, result, extra], index) => c(text, result, index, extra)),
  ...(roles.length ? { roles } : {})
});

